let archiveYear=null,archiveId=null,archiveReturn=null;
function archiveMatchMarkup(m){
 if(!m.valid)return '<p class="archive-empty">'+escapeText(m.reason)+'</p>';const esc=escapeText,played=m.players.filter(p=>p.minutes>0).sort((a,b)=>Number(b.started)-Number(a.started)||b.minutes-a.minutes||a.id.localeCompare(b.id)),rest=m.players.filter(p=>!p.minutes);
 return `<article class="archive-match"><div class="archive-score"><div><span>${m.year}시즌 · ${m.division}부 · ${esc(m.label)} · ${m.home?'홈':'원정'}</span><h3>${esc(S.club(S.own).short)} <b>${m.score[0]} : ${m.score[1]}</b> ${esc(m.opponent.short)}</h3></div><strong>${m.shootout?'승부차기 ':''}${m.outcome}</strong></div>${m.shootout?`<p class="archive-note">${m.penalties?'승부차기 '+m.penalties[0]+' : '+m.penalties[1]:'승부차기 세부 점수는 이 저장에 남아 있지 않습니다.'}</p>`:''}${m.partial?`<p class="archive-limited">이전 저장의 ${m.originMinute}분 이후 득점자 기록입니다.${m.unassignedGoals?' 선수 미지정 득점 '+m.unassignedGoals+'골.':''} 경기 최종 점수와 선수 출전 시간은 별도로 유지됩니다.</p>`:''}<section><h4>득점·카드·교체 기록</h4><p class="archive-note">득점 장면은 우리 구단 기록입니다. 상대 득점 시각과 같은 분 안의 세부 사건 순서는 저장되어 있지 않습니다.${m.cardsTracked?'':' 이 경기의 카드 기록도 남아 있지 않습니다.'}</p>${m.timeline.length?'<ol class="archive-timeline">'+m.timeline.map(e=>`<li class="archive-event ${e.type}"><strong>${e.minute}′</strong><div><b>${esc(e.title)}</b><span>${esc(e.detail)}</span></div></li>`).join('')+'</ol>':'<p class="archive-empty">표시할 세부 사건이 없습니다.</p>'}</section><section><h4>출전 선수 ${played.length}명</h4><div class="archive-player-list">${played.map(p=>`<article><div><strong>${esc(p.name)}</strong><small>${p.pos} · ${p.started?'선발':'교체 투입'}${p.owned?'':' · 당시 선수'}${p.redMinute!==null?' · '+p.redMinute+'분 퇴장':''}</small></div><span>${p.minutes}분</span><small>${p.goals}골 · ${p.assists}도움${p.cleanSheets?' · 무실점':''}</small></article>`).join('')}</div>${rest.length?'<details><summary>미출전 선수 '+rest.length+'명</summary><ul class="archive-rest">'+rest.map(p=>`<li>${esc(p.name)} · ${p.pos}${p.suspended?' · 출전 정지':' · 미출전'}</li>`).join('')+'</ul></details>':''}</section>${m.finance?`<div class="archive-finance"><span>이 경기 정산</span><strong>${seasonReviewMoney(m.finance.amount)}</strong><small>${m.competition==='league'?'선수·코치 급여 반영':'대회 경기 수입·상금'} · 이사회 과제·시즌 목표 보상은 별도</small></div>`:'<p class="archive-note">이 경기의 재정 장부가 남아 있지 않습니다.</p>'}</article>`;
}
function renderMatchArchive(){
 const dialog=$('match-archive-dialog');if(!dialog?.open)return;const years=MatchArchive.years(season);if(!years.includes(archiveYear))archiveYear=season.year;const matches=MatchArchive.list(season,archiveYear);if(!matches.some(m=>m.id===archiveId))archiveId=matches.at(-1)?.id||null;
 const m=archiveId?MatchArchive.read(season,archiveId):{valid:false,reason:'이 시즌의 상세 경기 기록이 없습니다. 구버전에서 사라진 기록은 추정하지 않습니다.'},esc=escapeText;
 dialog.innerHTML=`<div class="archive-head"><div><span class="eyebrow">MATCH ARCHIVE</span><h2 id="match-archive-title">우리 구단 경기 기록</h2></div><button type="button" id="close-match-archive" class="secondary" aria-label="경기 기록 닫기">×</button></div><div class="archive-body"><div class="archive-filters"><label>시즌<select id="archive-year">${years.map(y=>`<option value="${y}"${y===archiveYear?' selected':''}>${y}시즌</option>`).join('')}</select></label><label>경기<select id="archive-match"${matches.length?'':' disabled'}>${matches.length?matches.map(x=>`<option value="${esc(x.id)}"${x.id===archiveId?' selected':''}>${esc(x.label)} · ${esc(x.opponent)} · ${x.score[0]}:${x.score[1]}</option>`).join(''):'<option>기록 없음</option>'}</select></label></div>${archiveMatchMarkup(m)}</div>`;
 const close=()=>{dialog.close();archiveReturn?.focus?.({preventScroll:true});};$('close-match-archive').onclick=close;dialog.oncancel=e=>{e.preventDefault();close();};
 $('archive-year').onchange=e=>{archiveYear=Number(e.target.value);archiveId=null;renderMatchArchive();$('archive-year').focus({preventScroll:true});};$('archive-match').onchange=e=>{archiveId=e.target.value;renderMatchArchive();$('archive-match').focus({preventScroll:true});};
}
function openMatchArchive(id=null,year=season.year){const dialog=$('match-archive-dialog');if(!dialog)return;pauseForPlanning();archiveReturn=document.activeElement;archiveYear=year;archiveId=id;if(id){const record=MatchArchive.read(season,id);if(record.valid)archiveYear=record.year;}if(!dialog.open)dialog.showModal();renderMatchArchive();$('close-match-archive').focus({preventScroll:true});}
